 static net.minecraft.world.phys.Vec3 Vec3Center(BlockPos pos){return net.minecraft.world.phys.Vec3.atCenterOf(pos);}
 static List<BlockPos> path(ServerPlayer p,BlockPos from,BlockPos to,List<AABB> forbidden,int minX,int maxX,int minZ,int maxZ){var level=p.serverLevel();var previous=new HashMap<BlockPos,BlockPos>();var queue=new ArrayDeque<BlockPos>();previous.put(from,from);queue.add(from);while(!queue.isEmpty()){var at=queue.removeFirst();if(at.equals(to)){var result=new ArrayList<BlockPos>();var node=to;while(!node.equals(from)){result.add(node);node=previous.get(node);}result.add(from);return result;}for(var side:Direction.Plane.HORIZONTAL){var next=at.relative(side);if(next.getX()<minX||next.getX()>maxX||next.getZ()<minZ||next.getZ()>maxZ||previous.containsKey(next)||forbidden.stream().anyMatch(b->b.contains(Vec3Center(next))))continue;var s=level.getBlockState(next);boolean material=s.isAir()||s.is(Blocks.STONE_BRICKS)||s.is(Blocks.COBBLESTONE)||s.is(Blocks.DIRT_PATH)||s.is(net.minecraft.tags.BlockTags.PLANKS)||s.getBlock() instanceof StairBlock||s.getBlock() instanceof SlabBlock;if(!material||!level.getBlockState(next.above()).getCollisionShape(level,next.above()).isEmpty()||!level.getBlockState(next.above(2)).getCollisionShape(level,next.above(2)).isEmpty())continue;previous.put(next,at);queue.addLast(next);}}var obstacles=new TreeMap<String,Integer>();for(int x=minX;x<=maxX;x++)for(int z=minZ;z<=maxZ;z++){var at=new BlockPos(x,from.getY(),z);var type=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(level.getBlockState(at).getBlock()).toString();obstacles.merge(type,1,Integer::sum);}throw new IllegalStateException("No clear private fixture route between intact service approaches "+from+" / "+to+" reached="+previous.size()+" floorTypes="+obstacles);}
 static void attend(ServerPlayer p,ServerPlayer admin,BlockPos center){p.moveTo(center.getX()+.5,center.getY(),center.getZ()+.5);admin.moveTo(center.getX()+1.5,center.getY(),center.getZ()+.5);p.serverLevel().getChunkSource().move(p);p.serverLevel().getChunkSource().move(admin);}
 static void masterService(GameTestHelper h,ServerPlayer p,com.mohymods.kingdomsmp.persistence.ConstructionStore.Project project)throws Exception{var server=p.server;var store=CommerceService.store(server);String id="kingdom_smp:builder/m06";h.assertTrue(store.commissionContractPeriods(p.getUUID(),id)==0,"Old Apprentice/weekly records cannot become new Master-period evidence");var rules=server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(server);var data=JsonParser.parseString(Files.readString(rules)).getAsJsonObject();data.getAsJsonObject("goals").addProperty(id,1);Files.writeString(rules,new GsonBuilder().setPrettyPrinting().create().toJson(data));CommissionQuestRules.clear(server);CreateCraftRuntime.counter(p,project);var terms=ContractRules.get(server).get("builder/daily");h.assertTrue(p.getInventory().add(new ItemStack(terms.item(),terms.quantity())),"Explicit raw private contract supplies fit genuine native inventory");long purse=store.balance(p.getUUID()),spent=store.contractPoolSpent("daily",ContractRules.period("daily"));int stock=p.getInventory().countItem(terms.item());var quote=ContractService.review(p,"builder/daily");var old=p.getInventory().getItem(8).copy();p.getInventory().setItem(8,new ItemStack(Items.DIRT));boolean denied=false;try{ContractService.confirm(p,quote.nonce());}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.balance(p.getUUID())==purse&&store.contractPoolSpent("daily",ContractRules.period("daily"))==spent,"Changed native inventory refuses financial preparation/debit/reservation");p.getInventory().setItem(8,old);quote=ContractService.review(p,"builder/daily");ContractService.confirm(p,quote.nonce());h.assertTrue(p.getInventory().countItem(terms.item())==stock-terms.quantity()&&store.contractPoolSpent("daily",ContractRules.period("daily"))==spent+terms.reward()&&store.balance(p.getUUID())==purse&&store.commissionContractPeriods(p.getUUID(),id)==1,"Native material consumed once, finite actual funded mail reserved once, current Master band receipt only");denied=false;try{ContractService.confirm(p,quote.nonce());}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Repeated native financial confirmation cannot duplicate mail or consumption");var q=ProfessionService.review(p,"quest:"+id);ProfessionService.confirm(p,q.nonce());h.assertTrue(store.professions(p.getUUID()).track(Profession.BUILDER).xp()==4200,"Actual Master service earns300XPonce under explicit private period acceleration");CommerceService.verifyReceipt(p);}
